R1 = ["refs/ice_dragon_1_flat.jpg", "refs/wind_dragon_1_flat.jpg", "refs/seris_dragon_king_1_flat.jpg", "refs/seris_pixel_sprite_x2.png"]

DRAGON_FORM = """TRUE FORM: a great white-silver water dragon, long serpentine neck and body, silver-white scales with pale blue belly plates, glowing cyan eyes, swept-back silver horns, a flowing deep-blue mane, large wings with deep-blue membranes and silver wing bones, a long tail with a blue fin."""

